// intent: Verify to_bson serializes various integer types into BSON format correctly.
#include <nlohmann/json.hpp>
#include <iostream>
#include <vector>

int main() {
    try {
        nlohmann::json j = {{"i32", 12345}, {"i64", 1234567890123LL}};
        std::vector<std::uint8_t> v = nlohmann::json::to_bson(j);
        std::cout << "size: " << v.size() << std::endl;
    } catch (const std::exception& e) {
        std::cout << "Exception: " << e.what() << std::endl;
    }
}
